/// <reference types="astro/client" />
/// <reference types="@astrojs/cloudflare/types.d.ts" />

// Bindings, variables and secrets of the Worker (wrangler.jsonc, .dev.vars.example).
// Written by hand rather than generated by `wrangler types`, because they are optional to the type system:
// the static pages work without any of them, while the form refuses enquiries without DB (and, outside
// development, without IP_HASH_SALT; in production also without TURNSTILE_SECRET_KEY). See README.
declare namespace Cloudflare {
  interface Env {
    ASSETS: Fetcher;
    DB?: D1Database;
    /** Cloudflare Email Service send_email binding (production only; the preview has none) */
    EMAIL?: SendEmail;
    /** "production" (wrangler.jsonc), "preview" (env.preview) or "development" (.dev.vars) */
    SITE_ENV?: string;
    ENQUIRY_NOTIFY_TO?: string;
    ENQUIRY_FROM_EMAIL?: string;
    NOTIFY_DISABLED?: string;
    TURNSTILE_SECRET_KEY?: string;
    ADMIN_USER?: string;
    ADMIN_PASSWORD?: string;
    /** HMAC key for the IP hash; required in production and preview */
    IP_HASH_SALT?: string;
  }
}
// eslint-disable-next-line @typescript-eslint/no-empty-object-type -- the global Env the adapter's types expect
interface Env extends Cloudflare.Env {}

interface ImportMetaEnv {
  readonly PUBLIC_TURNSTILE_SITE_KEY?: string;
  readonly PUBLIC_GOOGLE_ADS_ID?: string;
  readonly PUBLIC_GOOGLE_ADS_CONVERSION_LABEL?: string;
}
